/**
 * PLM Automation : sends the content of this workbook to the local application (read only).
 *
 * Deployed as a web app by gsheet/install.mjs (clasp). JETON is defined in Secret.js, generated by the
 * installer and never committed: only the application that knows it can read the workbook.
 */

// Opened once by the installer: Google then asks to authorise the script.
function doGet() {
  return HtmlService.createHtmlOutput("<p style='font-family:sans-serif'>PLM Automation: reading allowed. This page can be closed.</p>");
}

// Called by the local server (backend/src/sheetSource.ts) in JSON, with the Google token of the account signed in to clasp.
function doPost(e) {
  let d;
  try {
    d = JSON.parse(e.postData.contents);
  } catch (err) {
    return reply({ error: "Unreadable request." });
  }
  if (!d || d.jeton !== JETON) return reply({ error: "Token refused: run gsheet/install.mjs again." });
  try {
    const book = SpreadsheetApp.getActiveSpreadsheet();
    const sheets = {};
    // Displayed values, like the "Download as .xlsx" file would give ("1,35", "0010").
    book.getSheets().forEach((sheet) => {
      if (sheet.getLastRow() > 0 && sheet.getLastColumn() > 0) sheets[sheet.getName()] = sheet.getDataRange().getDisplayValues();
    });
    return reply({ name: book.getName(), sheets: sheets });
  } catch (err) {
    return reply({ error: "The workbook could not be read: " + err });
  }
}

function reply(object) {
  return ContentService.createTextOutput(JSON.stringify(object)).setMimeType(ContentService.MimeType.JSON);
}
